    86	 *
    87	 * @details 为什么必须做（2026-09-27，PSRAM 写回审计的 G1）：EPIC 是**绕过 CPU 缓存**
    88	 *          直接写内存的 master。CPU 只要在那些像素上有缓存行（写过或读过就会留下），
    89	 *          读回来就是**旧像素**。目的缓冲在 PSRAM（画布 0x60E00000）时这条一定成立 ——
    90	 *          PSRAM 是 cacheable，且产品默认已是写回（`CONFIG_MYVENDOR_PSRAM_CACHE_WB=y`）。
    91	 *
    92	 * @warning ① **只作废矩形内的行**，不要图省事整层作废 —— 矩形外的像素 CPU 可能正握着刚
    93	 *          写的数据（写回模式下是脏行），一并作废就是**丢数据**；
    94	 * @warning ② 只在缓冲位于 PSRAM 时做（判据同芯片的 `IS_DCACHED_RAM`：地址 ≥ 0x60000000；
    95	 *          SRAM 不在缓存范围内，做了纯属浪费）；
    96	 * @warning ③ 依赖"包装返回时硬件必定已停"这个既有约定（见文件头：NuttX 上的
    97	 *          `HAL_EPIC_*Start*` 是 polling 版）—— 换成 `_IT` 版就必须挪到回调里。
    98	 */
    99	static void epic_invalidate_rect_rows(const void * rect_tl, uint32_t stride,
   100	  int32_t w, int32_t h)
   101	{
   102	  int32_t i;
   103	
   104	  if ((uintptr_t)rect_tl < 0x60000000u || w <= 0 || h <= 0)
   105	    {
   106	      return;
   107	    }
   108	
   109	  for (i = 0; i < h; i++)
   110	    {
   111	      uintptr_t row = (uintptr_t)rect_tl + (uintptr_t)i * stride;
   112	
   113	      up_invalidate_dcache(row, row + (uintptr_t)w * sizeof(uint16_t));
   114	    }
   115	}
