   256	bool myvendor_epic_busy(void)
   257	{
   258	  EPIC_HandleTypeDef *epic = lv_epic_get_handle();
   259	
   260	  if (epic == NULL || epic->Instance == NULL)
   261	    {
   262	      return false;
