   279	/** @brief 旋转的实际实现（公开入口只负责计时探针，测完删）。 */
   280	static bool myvendor_epic_rotate_impl(const uint16_t * src_buf,
   281	  uint32_t src_stride, int32_t src_w, int32_t src_h, uint16_t * dst_buf,
   282	  uint32_t dst_stride, int32_t dst_w, int32_t dst_h, int32_t angle10,
   283	  int32_t pivot_x, int32_t pivot_y, int32_t dst_cx, int32_t dst_cy,
   284	  int32_t clip_x, int32_t clip_y, int32_t clip_w, int32_t clip_h);
   285	
   286	/**
   287	 * @brief 子矩形旋转的可用性。**默认关**，只有开机自检明确 PASS 才打开。
   288	 *
   289	 * @details 默认开会在"自检还没跑（或整幅自检提前 SKIP）"时放行未经像素比对的
   290	 *          子矩形路径；默认关时最坏只是少一项优化，退回整幅（正确性优先）。
   291	 */
   292	static bool s_rotate_area_ok = false;
   293	
   294	/**
   295	 * @brief RGB565 整层旋转：把 `src` 绕 (pivot_x, pivot_y) 转 `angle10`（0.1°）后，
   296	 *        让这个 pivot 落在 `dst` 的 (dst_cx, dst_cy)。
   297	 *
   298	 * @details 摆法照抄 LVGL 适配层（`lv_epic_setup_layers` + `lv_draw_sifli_epic_img`）：
   299	 *          bg = 目的整层，fg = 源整层 + `transform_cfg`，两者在**同一个坐标空间**里，
   300	 *          fg 的 `x_offset/y_offset` 决定"源的左上角摆在哪" ⇒ 让 pivot 落在
   301	 *          (dst_cx,dst_cy) 就是 `offset = dst_c - pivot`。pivot 按 HAL 注释是
   302	 *          "base on VideoLayer's origin"，即**源缓冲的像素坐标**。
   303	 *
   304	 * @note 同步（包装底下是 polling 版 HAL），返回时硬件已停。
   305	 * @note 源先 clean、目的按行 invalidate（PSRAM 写回缓存的前提）。
   306	 * @return true = 已执行；false = 参数越界/硬件不可用，**什么都没做**。
   307	 */
   308	bool myvendor_epic_rotate(const uint16_t * src_buf, uint32_t src_stride,
   309	  int32_t src_w, int32_t src_h, uint16_t * dst_buf, uint32_t dst_stride,
   310	  int32_t dst_w, int32_t dst_h, int32_t angle10, int32_t pivot_x,
   311	  int32_t pivot_y, int32_t dst_cx, int32_t dst_cy)
   312	{
   313	  if (!myvendor_epic_ready() || src_buf == NULL || dst_buf == NULL)
   314	    {
   315	      return false;
   316	    }
   317	
   318	  /* 【临时探针】旋转耗时统计（[vrot]，LOG_DEBUG，`ctl log all` 可见）。测完删。 */
   319	  {
   320	    static struct
   321	    {
   322	      uint32_t n;
   323	      uint32_t sum;
   324	      uint32_t max;
   325	      uint32_t win;
   326	    } pf;
   327	    uint32_t t0 = clock_systime_ticks();
   328	    bool r = myvendor_epic_rotate_impl(src_buf, src_stride, src_w, src_h,
   329	      dst_buf, dst_stride, dst_w, dst_h, angle10, pivot_x, pivot_y, dst_cx,
   330	      dst_cy, 0, 0, dst_w, dst_h);
   331	    uint32_t ms = (uint32_t)(clock_systime_ticks() - t0);
   332	    uint32_t win;
   333	
   334	    if (pf.win == 0u)
   335	      {
   336	        pf.win = clock_systime_ticks();
   337	      }
   338	    if (r)
   339	      {
   340	        pf.n++;
   341	        pf.sum += ms;
   342	        if (ms > pf.max)
   343	          {
   344	            pf.max = ms;
   345	          }
   346	      }
   347	    win = (uint32_t)(clock_systime_ticks() - pf.win);
   348	    if (win >= 2000u)
   349	      {
   350	        if (pf.n > 0u)
   351	          {
   352	            syslog(LOG_DEBUG, "[vrot] bakes n=%u avg=%ums max=%ums win=%ums",
   353	              (unsigned)pf.n, (unsigned)(pf.sum / pf.n), (unsigned)pf.max,
   354	              (unsigned)win);
   355	          }
   356	        pf.n = 0u;
   357	        pf.sum = 0u;
   358	        pf.max = 0u;
   359	        pf.win = clock_systime_ticks();
   360	      }
   361	    return r;
   362	  }
   363	}
   364	
   365	static bool myvendor_epic_rotate_impl(const uint16_t * src_buf,
   366	  uint32_t src_stride, int32_t src_w, int32_t src_h, uint16_t * dst_buf,
   367	  uint32_t dst_stride, int32_t dst_w, int32_t dst_h, int32_t angle10,
   368	  int32_t pivot_x, int32_t pivot_y, int32_t dst_cx, int32_t dst_cy,
   369	  int32_t clip_x, int32_t clip_y, int32_t clip_w, int32_t clip_h)
   370	{
   371	  EPIC_LayerConfigTypeDef layers[2];
   372	  EPIC_LayerConfigTypeDef out;
   373	  int32_t x0;
   374	  int32_t y0;
   375	  int32_t x1;
   376	  int32_t y1;
   377	  int32_t sy0;
   378	  int32_t sy1;
   379	  bool clipped;
   380	  bool ok;
   381	  const uint32_t wt_before = g_epic_wait_timeouts;
   382	
   383	  if (src_w <= 0 || src_h <= 0 || dst_w <= 0 || dst_h <= 0
   384	      || angle10 < 0 || angle10 >= 3600)
   385	    {
   386	      return false;
   387	    }
   388	
   389	  /* 坐标寄存器 10 bit（EPIC_COORDINATES_MAX = 1010），越界 HAL 会断言。 */
   390	  if (src_w > EPIC_COORDINATES_MAX || src_h > EPIC_COORDINATES_MAX
   391	      || dst_w > EPIC_COORDINATES_MAX || dst_h > EPIC_COORDINATES_MAX)
   392	    {
   393	      return false;
   394	    }
   395	
   396	  /* 行区间初值放在尺寸校验**之后**：`src_h - 1` 在 src_h=INT32_MIN 时是有符号溢出。 */
   397	  sy0 = src_h - 1;
   398	  sy1 = 0;
   399	
   400	  /* 非正尺寸 ⇒ 无事可做。**必须在算端点之前判**：`cli…2280 tokens truncated…件事 —— 都只在"整幅对、子矩形错"时才会暴露：
   604	 *          ① clip 内与整幅**逐像素相同**（验 HAL 的 data/x_offset 契约与反投影相位）；
   605	 *          ② clip 外**一个像素都没被写**（验输出层裁剪语义）。
   606	 *          源/目的缓冲与 `myvendor_epic_rotate_selftest()` 共用，额外只占一个
   607	 *          20x20 快照（800 B）。背景先灌 SENTINEL 再烘：整幅路径里"没被前景覆盖"
   608	 *          的像素会保持背景色，这样两条路径的判据才一致。
   609	 */
   610	static bool epic_rotate_area_selftest(uint16_t * src, uint16_t * dst,
   611	  int32_t src_w, int32_t src_h, int32_t dst_w, int32_t dst_h, int32_t angle10,
   612	  int32_t piv)
   613	{
   614	  enum
   615	  {
   616	    CLIP_X = 14, CLIP_Y = 14, CLIP_W = 20, CLIP_H = 20, SENTINEL = 0xA5A5
   617	  };
   618	  static uint16_t snap[CLIP_W * CLIP_H];
   619	  int32_t x;
   620	  int32_t y;
   621	  int32_t bad_in = 0;
   622	  int32_t bad_out = 0;
   623	
   624	  for (y = 0; y < dst_h; y++)
   625	    {
   626	      for (x = 0; x < dst_w; x++)
   627	        {
   628	          dst[y * dst_w + x] = SENTINEL;
   629	        }
   630	    }
   631	
   632	  if (!myvendor_epic_rotate_impl(src, (uint32_t)src_w * sizeof(uint16_t),
   633	          src_w, src_h, dst, (uint32_t)dst_w * sizeof(uint16_t), dst_w, dst_h,
   634	          angle10, piv, piv, dst_w / 2, dst_h / 2, 0, 0, dst_w, dst_h))
   635	    {
   636	      syslog(LOG_WARNING, "[vrot] area selftest SKIP: full rotate failed");
   637	      return false;
   638	    }
   639	
   640	  for (y = 0; y < CLIP_H; y++)
   641	    {
   642	      for (x = 0; x < CLIP_W; x++)
   643	        {
   644	          snap[y * CLIP_W + x] = dst[(CLIP_Y + y) * dst_w + CLIP_X + x];
   645	        }
   646	    }
   647	
   648	  for (y = 0; y < dst_h; y++)
   649	    {
   650	      for (x = 0; x < dst_w; x++)
   651	        {
   652	          dst[y * dst_w + x] = SENTINEL;
   653	        }
   654	    }
   655	
   656	  if (!myvendor_epic_rotate_impl(src, (uint32_t)src_w * sizeof(uint16_t),
   657	          src_w, src_h, dst, (uint32_t)dst_w * sizeof(uint16_t), dst_w, dst_h,
   658	          angle10, piv, piv, dst_w / 2, dst_h / 2, CLIP_X, CLIP_Y, CLIP_W,
   659	          CLIP_H))
   660	    {
   661	      syslog(LOG_WARNING, "[vrot] area selftest SKIP: rotate_area failed");
   662	      return false;
   663	    }
   664	
   665	  for (y = 0; y < dst_h; y++)
   666	    {
   667	      for (x = 0; x < dst_w; x++)
   668	        {
   669	          const bool in = (x >= CLIP_X && x < CLIP_X + CLIP_W
   670	            && y >= CLIP_Y && y < CLIP_Y + CLIP_H);
   671	          const uint16_t got = dst[y * dst_w + x];
   672	
   673	          if (in)
   674	            {
   675	              if (got != snap[(y - CLIP_Y) * CLIP_W + (x - CLIP_X)])
   676	                {
   677	                  bad_in++;
   678	                }
   679	            }
   680	          else if (got != SENTINEL)
   681	            {
   682	              bad_out++;
   683	            }
   684	        }
   685	    }
   686	
   687	  syslog((bad_in == 0 && bad_out == 0) ? LOG_NOTICE : LOG_WARNING,
   688	    "[vrot] area selftest %s: in=%d out=%d (clip %d,%d %dx%d)",
   689	    (bad_in == 0 && bad_out == 0) ? "PASS" : "FAIL", (int)bad_in,
   690	    (int)bad_out, CLIP_X, CLIP_Y, CLIP_W, CLIP_H);
   691	
   692	  return (bad_in == 0 && bad_out == 0);
   693	}
   694	
   695	/**
   696	 * @brief 旋转自检：用"像素里编码自己坐标"的图案转一次，抽查若干目的点。
   697	 *
   698	 * @details 判据是**坐标**而不是颜色：源 32x32 每像素写 (x<<11)|(y<<5)，
